59	
60		@SuppressWarnings("unchecked")
61		public ClientResultMap createChecklistResult(ParamMap param) throws LogicException {
62			ClientResultMap result = new ClientResultMap();
63			int loggerStep = 0;
64	
65			DataSourceTransactionManager txManager = getDataSourceTransactionManager();
66			TransactionStatus txStatus = txManager.getTransaction(new DefaultTransactionDefinition());
67	
68			try {
69				logger.info("[STEP{}] - Validate deviceInfo", ++loggerStep);
70				Map<String, Object> deviceInfo = (Map<String, Object>) param.get("deviceInfo");
71				if (deviceInfo == null || deviceInfo.toString().isEmpty()) {
72					throw new LogicException(Constants.DEVICE_INFO_IS_REQUIRED_MSG, Constants.DEVICE_INFO_IS_REQUIRED_CODE);
73				}
74	
75				List<Map<String, Object>> results = (List<Map<String, Object>>) param.get("results");
76				if (results == null || results.isEmpty()) {
77					throw new LogicException(Constants.RESULTS_IS_REQUIRED_MSG, Constants.RESULTS_IS_REQUIRED_CODE);
78				}
79	
80				logger.info("[STEP{}] - Insert checklist result master", ++loggerStep);
81				ParamMap masterParam = new ParamMap();
82				masterParam.put("manufacturer", deviceInfo.get("manufacturer"));
83				masterParam.put("model", deviceInfo.get("model"));
84				masterParam.put("osVersion", deviceInfo.get("osVersion"));
85				masterParam.put("appVersion", deviceInfo.get("appVersion"));
86				masterParam.put("uuid", deviceInfo.get("uuid"));
87	
88				dao.insertChecklistResult(masterParam);
89				long checklistResultSeq = masterParam.getLong("checklistResultSeq");
90				logger.info("[STEP{}] - Master inserted, checklistResultSeq: {}", ++loggerStep, checklistResultSeq);
91	
92				logger.info("[STEP{}] - Insert checklist result detail", ++loggerStep);
93				for (Map<String, Object> item : results) {
94					long timestamp = ((Number) item.get("testDate")).longValue();
95					item.put("testDate", new java.sql.Timestamp(timestamp));
96				}
97				ParamMap detailParam = new ParamMap();
98				detailParam.put("checklistResultSeq", checklistResultSeq);
99				detailParam.put("results", results);
100				dao.insertChecklistResultDetail(detailParam);
101				txManager.commit(txStatus);
102				logger.info("[STEP{}] - Transaction committed", ++loggerStep);
103			} catch (LogicException le) {
104				txManager.rollback(txStatus);
105				logger.error("LogicException: code={}, message={}", le.getCode(), le.getMessage());
