	@SuppressWarnings("unchecked")
	public ClientResultMap createChecklistResult(ParamMap param) throws LogicException {
		ClientResultMap result = new ClientResultMap();
		int loggerStep = 0;

		DataSourceTransactionManager txManager = getDataSourceTransactionManager();
		TransactionStatus txStatus = txManager.getTransaction(new DefaultTransactionDefinition());

		try {
			logger.info("[STEP{}] - Validate deviceInfo", ++loggerStep);
			Map<String, Object> deviceInfo = (Map<String, Object>) param.get("deviceInfo");
			if (deviceInfo == null || deviceInfo.toString().isEmpty()) {
				throw new LogicException(Constants.DEVICE_INFO_IS_REQUIRED_MSG, Constants.DEVICE_INFO_IS_REQUIRED_CODE);
			}

			List<Map<String, Object>> results = (List<Map<String, Object>>) param.get("results");
			if (results == null || results.isEmpty()) {
				throw new LogicException(Constants.RESULTS_IS_REQUIRED_MSG, Constants.RESULTS_IS_REQUIRED_CODE);
			}

			logger.info("[STEP{}] - Insert checklist result master", ++loggerStep);
			ParamMap masterParam = new ParamMap();
			masterParam.put("manufacturer", deviceInfo.get("manufacturer"));
			masterParam.put("model", deviceInfo.get("model"));
			masterParam.put("osVersion", deviceInfo.get("osVersion"));
			masterParam.put("appVersion", deviceInfo.get("appVersion"));
			masterParam.put("uuid", deviceInfo.get("uuid"));

			dao.insertChecklistResult(masterParam);
			long checklistResultSeq = masterParam.getLong("checklistResultSeq");
			logger.info("[STEP{}] - Master inserted, checklistResultSeq: {}", ++loggerStep, checklistResultSeq);

			logger.info("[STEP{}] - Insert checklist result detail", ++loggerStep);
			for (Map<String, Object> item : results) {
				long timestamp = ((Number) item.get("testDate")).longValue();
				item.put("testDate", new java.sql.Timestamp(timestamp));
			}
			ParamMap detailParam = new ParamMap();
			detailParam.put("checklistResultSeq", checklistResultSeq);
			detailParam.put("results", results);
			dao.insertChecklistResultDetail(detailParam);
			txManager.commit(txStatus);
			logger.info("[STEP{}] - Transaction committed", ++loggerStep);
		} catch (LogicException le) {
			txManager.rollback(txStatus);
			logger.error("LogicException: code={}, message={}", le.getCode(), le.getMessage());
			result.setCode(le.getCode());
			result.setMessage(le.getMessage());
		} catch (Exception e) {
			txManager.rollback(txStatus);
			logger.error("Exception: {}", e.getMessage());
			result.setCode(Constants.UNKNOWN_ERR_CODE);
			result.setMessage(e.getMessage());
		}

		return result;
	}

	public ClientResultMap  checkAppVersion(ParamMap param) throws Exception {
		ClientResultMap result = new ClientResultMap();

		String installedVersion = param.getString("installedVersion");
		if (installedVersion == null || installedVersion.isEmpty()) {
			throw new LogicException(Constants.APP_VERSION_IS_REQUIRED_MSG, Constants.APP_VERSION_IS_REQUIRED_CODE);
		}

		Map<String, Object> latestInfo = dao.getLatestAppVersion();
		if (latestInfo == null) {
			throw new LogicException(Constants.LATEST_APP_VERSION_NOT_FOUND_MSG, Constants.LATEST_APP_VERSION_NOT_FOUND_CODE);
		}

		String latestVersion = (String) latestInfo.get("appVersion");
		String updateUrl = (String) latestInfo.get("updateUrl");

		String updateType;
		if (compareVersion(installedVersion, latestVersion) >= 0) {
			updateType = Constants.UPDATE_TYPE_NONE;
			updateUrl = null;
		} else {
			updateType = Constants.UPDATE_TYPE_OPTIONAL;
		}

		Map<String, Object> data = new java.util.HashMap<>();
		data.put("updateType", updateType);
		data.put("updateUrl", updateUrl);
		result.setData(data);

		return result;
	}

