package com.ahope.ds.client.controller;

import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import io.restassured.response.Response;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller ClientAPIController (src/main/java/com/ahope/ds/client/controller/ClientAPIController.java)
 * @target-api GET /client/sync
 *
 * Test Coverage:
 * - NTC: Verify successful sync response with all required fields
 * - VTC: Authorization header validation
 * - ATC: Unauthorized/missing token scenarios
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class ClientSyncBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mariadb://localhost:3306/smartplant");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "root");
    private static final String WIREMOCK_URL = System.getProperty("test.wiremock.url", "http://localhost:9090");

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private String testId(TestInfo info) {
        return String.format("T%09d",
            Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    /**
     * NTC: Successful sync - verify response contains all required fields
     * Happy path: Valid authorization token, returns latest versions and sync data
     */
    @Test
    void NTC_clientSync_success(TestInfo info) throws Exception {
        String id = testId(info);

        // Given: Setup test data
        try {
            executeSqlTemplate("sql/client-sync-setup.sql", Map.of("CLIENT_SEQ", id, "MEMBER_SEQ", id));

            // When: Call sync endpoint with valid auth token
            Response response = given().log().all()
                .baseUri(BASE_URL)
                .header("Authorization", "Bearer validAccessToken_" + id)
                .header("X-Requested-With", "XMLHttpRequest")
                .contentType(ContentType.JSON)
            .when()
                .get("/client/sync")
            .then().log().all()
                .statusCode(200)
                .extract().response();

            // Then: Verify response structure
            String responseBody = response.getBody().asString();
            assertTrue(responseBody.contains("latestTermsVersion"), "Response should contain latestTermsVersion");
            assertTrue(responseBody.contains("latestNoticeVersion"), "Response should contain latestNoticeVersion");
            assertTrue(responseBody.contains("mainBackgroundImageUrl"), "Response should contain mainBackgroundImageUrl");
            assertTrue(responseBody.contains("interlockingAppList"), "Response should contain interlockingAppList");
            assertTrue(responseBody.contains("allowedEcgiList"), "Response should contain allowedEcgiList");
            assertTrue(responseBody.contains("solutionList"), "Response should contain solutionList");

        } finally {
            executeSqlTemplate("sql/client-sync-teardown.sql", Map.of("CLIENT_SEQ", id, "MEMBER_SEQ", id));
        }
    }

    /**
     * VTC_Authorization_MISSING: Missing Authorization header
     * Expected: 401 Unauthorized or JSON error response
     */
    @Test
    void VTC_Authorization_MISSING(TestInfo info) throws Exception {
        given().log().all()
            .baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.JSON)
        .when()
            .get("/client/sync")
        .then().log().all()
            .statusCode(401);
    }

    /**
     * VTC_Authorization_INVALID: Invalid Authorization token
     * Expected: 401 Unauthorized
     */
    @Test
    void VTC_Authorization_INVALID(TestInfo info) throws Exception {
        given().log().all()
            .baseUri(BASE_URL)
            .header("Authorization", "Bearer invalidToken")
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.JSON)
        .when()
            .get("/client/sync")
        .then().log().all()
            .statusCode(401);
    }

    /**
     * VTC_Authorization_EMPTY: Empty Authorization header value
     * Expected: 401 Unauthorized
     */
    @Test
    void VTC_Authorization_EMPTY(TestInfo info) throws Exception {
        given().log().all()
            .baseUri(BASE_URL)
            .header("Authorization", "")
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.JSON)
        .when()
            .get("/client/sync")
        .then().log().all()
            .statusCode(401);
    }

    /**
     * ATC_NoClientData: Authorized but no client data in session
     * Expected: Returns response but with empty/null data fields
     */
    @Test
    void ATC_NoClientData(TestInfo info) throws Exception {
        String id = testId(info);

        // Given: No setup data (client not found)
        Response response = given().log().all()
            .baseUri(BASE_URL)
            .header("Authorization", "Bearer unknownClient_" + id)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.JSON)
        .when()
            .get("/client/sync")
        .then().log().all()
            .statusCode(200)
            .extract().response();

        // Then: Should return 200 but with potentially empty data
        assertTrue(response.getBody().asString().contains("data"), "Response should contain data field");
    }

    /**
     * Utility: Execute SQL template with parameter substitution
     */
    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             java.io.InputStream is = ClientSyncBlackBoxTest.class
                .getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {

            if (is == null) {
                System.err.println("SQL file not found: " + resourcePath + " (skipping)");
                return;
            }

            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (var entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }

            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) {
                    try {
                        stmt.execute(trimmed);
                    } catch (Exception e) {
                        System.err.println("SQL execution skipped (table may not exist): " + trimmed);
                    }
                }
            }
        } catch (Exception e) {
            System.err.println("SQL template execution skipped: " + resourcePath + " - " + e.getMessage());
        }
    }
}

